insert into impuestos(id,inmueble,concepto,tipo,nro_cliente,forma_pago,notas)
select d.id,p.id,d.concepto,d.tipo,d.nro_cliente,d.forma_pago,d.notas
from d join propiedades p on upper(p.direccion)=upper(d.inmueble)
on conflict (id) do nothing;

select count(*) as impuestos_en_la_base from impuestos;   -- tiene que dar 323
